func:
// Started with msg.payload = envelope {method,url,headers,query,body}
msg.request = msg.payload;
msg.payload = msg.request.body;
return msg;

// Terminal node: shapes the Temporal Workflow's captured lastMsg into a
// response descriptor {statusCode, headers, payload} for the sync-server
// bridge to write back as the real HTTP response.
msg.payload = {
    statusCode: 201,
    headers: { 'x-poc-node': 'n3' },
    payload: { echoed: msg.request.body || null, method: msg.request.method, receivedAt: Date.now() }
};
return msg;
